-- Tokens por hora do site antigo (cloudnexapro.site), últimos 30 dias até 15/11/2026 23h UTC.
-- Só totais por hora, sem nenhum dado de cliente. O painel admin soma isso aos números do site novo
-- (24 horas, 7 dias e 30 dias); com o tempo esses números saem da janela naturalmente.
CREATE TABLE IF NOT EXISTS public.legacy_usage_hourly (
  hour timestamptz PRIMARY KEY,
  tokens bigint NOT NULL DEFAULT 0
);
ALTER TABLE public.legacy_usage_hourly ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "admins read legacy usage" ON public.legacy_usage_hourly;
CREATE POLICY "admins read legacy usage" ON public.legacy_usage_hourly
  FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
GRANT SELECT ON public.legacy_usage_hourly TO authenticated;

